import configparser
import io
import json
import os
import re
from dataclasses import dataclass
from typing import Any, Sequence

import numpy as np
import requests
import torch
from PIL import Image

import folder_paths

from .qwen_pe_prompts import (
    API_MODE_LINE,
    FINAL_LANGUAGE_RULE_EN,
    FINAL_LANGUAGE_RULE_ZH,
    LOCAL_MODE_LINE,
    PE_LANGUAGE_RULE_EN,
    PE_LANGUAGE_RULE_ZH,
    QWEN_EDIT_SYSTEM_PROMPT,
    QWEN_OFFICIAL_PE_POLICY,
    QWEN_OUTPUT_POLICY,
    QWEN_T2I_SYSTEM_PROMPT,
)

MAX_REFERENCE_IMAGES = 9
DEFAULT_API_BASE_URL = "https://api.deepseek.com"
DEFAULT_API_MODEL = "deepseek-flash"
DEFAULT_IMAGE_MAX_EDGE = 2048
DEFAULT_IMAGE_MAX_PIXELS = 1_048_576
DEFAULT_MAX_OUTPUT_TOKENS = 4096
API_TIMEOUT = 600
API_TEMPERATURE = 0.6
PE_FOLDER = "text_encoders"
PE_TEMPERATURE = 0.7
PE_TOP_K = 20
PE_TOP_P = 0.95
PE_REPETITION_PENALTY = 1.05
JPEG_QUALITY = 90
DEFAULT_LONGEST_EDGE = 1024
LONGEST_EDGE_MULTIPLE = 32
MAX_SEED = 0xFFFFFFFFFFFFFFFF

MODE_AUTO = "自动"
MODE_TEXT_TO_IMAGE = "文生图"
MODE_IMAGE_TO_IMAGE = "图生图"
METHOD_PE = "本地官方PE"
METHOD_API = "API"

MISSING_MODEL_PLACEHOLDER = "（请把官方 PE 的 safetensors 放到 models/text_encoders 或 models/clip）"
REFERENCE_INPUT = "参考图"

# 这些主机的地址本身就已经是接口根，不再补 /v1。
_VERSIONLESS_API_HOSTS = frozenset({"api.deepseek.com"})
_USER_REQUEST_PREFIX = "用户需求：\n"
_EMPTY_REPLY_MESSAGE = "模型返回为空，可能只生成了思考内容但没有最终提示词。请提高最大生成token后重试。"

_CJK_RE = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")
_PLACEHOLDER_KEY_RE = re.compile(r"you[r]?[\s_-]*api[\s_-]*key", re.I)
_CODE_FENCE_RE = re.compile(r"```(?:json|text|markdown)?\s*([\s\S]*?)\s*```")
_THINK_PAIR_RE = re.compile(r"<think>[\s\S]*?</think>\s*", re.I)
_THINK_ORPHAN_RE = re.compile(r"^[\s\S]*?</think>\s*")
_THINK_ZH_RE = re.compile(r"<思考>[\s\S]*?</思考>\s*")
_THOUGHT_FENCE_RE = re.compile(r"```thought\b[\s\S]*?```")
_T2I_LANGUAGE_TAIL_RE = re.compile(r"\n\n## Language\n[\s\S]*\Z")
_EDIT_OUTPUT_TAIL_RE = re.compile(r"\n\n## Output [Ff]ormat\n[\s\S]*\Z")
_EDIT_LANGUAGE_BLOCK_RE = re.compile(
    r"\n\*\*FIRST — there are TWO separate language decisions\.[\s\S]*?"
    r"(?=\n\nYou are an expert at clarifying image editing instructions\.)"
)


def _first(value: Any, default: Any = None) -> Any:
    """INPUT_IS_LIST 会把每个输入包成列表，这里统一取第一个值。"""
    if isinstance(value, (list, tuple)):
        value = value[0] if len(value) else default
    return default if value is None else value


def _as_int(value: Any, default: int) -> int:
    try:
        return int(_first(value, default))
    except (TypeError, ValueError):
        return default


def _as_bool(value: Any, default: bool = False) -> bool:
    value = _first(value, default)
    if isinstance(value, str):
        return value.strip().lower() not in ("", "0", "false", "no", "off")
    return bool(value)


def _coerce_text(value: Any) -> str:
    """把不同 ComfyUI 版本 / 不同网关返回的文本结构统一成字符串。"""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("content", "text", "output", "output_text", "response"):
            if key in value:
                text = _coerce_text(value[key])
                if text:
                    return text
        return ""
    if isinstance(value, (list, tuple)):
        for item in value:
            text = _coerce_text(item)
            if text:
                return text
        return ""
    return str(value)


# --------------------------------------------------------------------------- #
# 官方 PE 模型
# --------------------------------------------------------------------------- #


def _pe_model_choices() -> list[str]:
    """官方 PE 只吃单文件 safetensors；GGUF 属于已经移除的「本地」通路。"""
    try:
        names = folder_paths.get_filename_list(PE_FOLDER)
    except Exception:
        names = []
    found = sorted({str(name) for name in names if str(name).lower().endswith(".safetensors")})
    return found or [MISSING_MODEL_PLACEHOLDER]


def _resolve_pe_model_path(model_name: str) -> str:
    return folder_paths.get_full_path_or_raise(PE_FOLDER, model_name)


@dataclass
class _OfficialPEModel:
    clip: Any
    model_name: str


class _OfficialPEStorage:
    """一次只驻留一个官方 PE 模型，换模型时先卸载再加载。"""

    model: "_OfficialPEModel | None" = None

    @classmethod
    def load(cls, model_name: str) -> _OfficialPEModel:
        if cls.model is not None and cls.model.model_name == model_name:
            return cls.model
        cls.unload()
        import comfy.sd

        if not hasattr(comfy.sd.CLIPType, "QWEN_IMAGE"):
            raise RuntimeError("当前 ComfyUI 版本不支持 Qwen Image 2.1 文本编码器，请更新 ComfyUI")
        clip = comfy.sd.load_clip(
            ckpt_paths=[_resolve_pe_model_path(model_name)],
            embedding_directory=folder_paths.get_folder_paths("embeddings"),
            clip_type=comfy.sd.CLIPType.QWEN_IMAGE,
        )
        cls.model = _OfficialPEModel(clip=clip, model_name=model_name)
        return cls.model

    @classmethod
    def unload(cls) -> None:
        model, cls.model = cls.model, None
        if model is None:
            return
        try:
            import comfy.model_management as model_management

            patcher = getattr(model.clip, "patcher", None)
            if patcher is not None:
                model_management.unload_model_and_clones(patcher)
            model_management.soft_empty_cache(force=True)
        except Exception:
            pass


# --------------------------------------------------------------------------- #
# 提示词模板
# --------------------------------------------------------------------------- #


def _remove_conflicting_language_rules(text: str) -> str:
    """去掉官方模板里与节点「输出语言」冲突的语言/输出格式段落。"""
    text = text.replace("one long English paragraph", "one long paragraph")
    text = _EDIT_LANGUAGE_BLOCK_RE.sub("", text)
    text = _T2I_LANGUAGE_TAIL_RE.sub("", text)
    text = _EDIT_OUTPUT_TAIL_RE.sub("", text)
    return text


def _clean_base_prompt(mode: str) -> str:
    base = QWEN_T2I_SYSTEM_PROMPT if mode == MODE_TEXT_TO_IMAGE else QWEN_EDIT_SYSTEM_PROMPT
    return _remove_conflicting_language_rules(base)


def _node_output_tail(language: str, *, api_mode: bool) -> str:
    rule = FINAL_LANGUAGE_RULE_ZH if language == "中文" else FINAL_LANGUAGE_RULE_EN
    line = API_MODE_LINE if api_mode else LOCAL_MODE_LINE
    return "\n\n" + QWEN_OUTPUT_POLICY + "\n" + rule + "\n" + line


def _build_system_prompt(mode: str, language: str, *, api_mode: bool) -> str:
    """原节点的节点级输出策略（API 通路与已移除的本地通用通路共用）。"""
    return mode + _node_output_tail(language, api_mode=api_mode)


def _build_api_instructions(mode: str, language: str) -> str:
    """API 通路的 instructions：官方规则 + 节点级输出策略。"""
    return _clean_base_prompt(mode) + _node_output_tail(language, api_mode=True)


def _build_official_pe_system(mode: str, language: str) -> str:
    """本地官方 PE 的 system：官方规则 + JSON 输出协议 + 语言规则。"""
    rule = PE_LANGUAGE_RULE_ZH if language == "中文" else PE_LANGUAGE_RULE_EN
    return _clean_base_prompt(mode) + "\n\n" + QWEN_OFFICIAL_PE_POLICY + "\n" + rule


def _build_official_pe_text(system: str, user_request: str, *, has_images: bool) -> str:
    """原节点手写的 Gemma 风格对话模板，图生图额外插入一个图像软 token。"""
    text = "<start_of_turn>system\n" + system + "<end_of_turn>\n<start_of_turn>user\n"
    if has_images:
        text += "\n<image_soft_token>\n\n"
    return text + "User Raw Input Prompt: " + user_request + ".<end_of_turn>\n<start_of_turn>model\n"


# --------------------------------------------------------------------------- #
# 结果解析
# --------------------------------------------------------------------------- #


def _clean_think_blocks(text: str) -> str:
    cleaned = _THINK_PAIR_RE.sub("", text or "")
    cleaned = _THINK_ZH_RE.sub("", cleaned)
    cleaned = _THINK_ORPHAN_RE.sub("", cleaned)
    cleaned = _THOUGHT_FENCE_RE.sub("", cleaned)
    return cleaned.strip()


def _strip_code_fence(text: str) -> str:
    cleaned = (text or "").strip()
    match = _CODE_FENCE_RE.fullmatch(cleaned)
    return match.group(1).strip() if match else cleaned


def _repair_mojibake(text: str) -> str:
    """把 latin-1 误解码出来的中文修回来，至少要有两个汉字才动手。"""
    if not text or _CJK_RE.search(text):
        return text
    try:
        repaired = text.encode("latin-1").decode("utf-8")
    except (UnicodeDecodeError, UnicodeEncodeError):
        return text
    if repaired == text or len(_CJK_RE.findall(repaired)) < 2:
        return text
    return repaired


def _parse_result(text: str) -> str:
    """优先取 JSON 里的 rewritten_prompt，取不到就把清理后的纯文本当结果。

    思考块由调用方先用 `_clean_think_blocks` 清掉，这里只负责代码块和 JSON。
    """
    cleaned = _repair_mojibake(_strip_code_fence(text))
    if not cleaned.strip():
        raise ValueError(_EMPTY_REPLY_MESSAGE)
    data: Any = None
    try:
        data = json.loads(cleaned)
    except (TypeError, ValueError):
        start, end = cleaned.find("{"), cleaned.rfind("}")
        if 0 <= start < end:
            try:
                data = json.loads(cleaned[start : end + 1])
            except (TypeError, ValueError):
                data = None
    if isinstance(data, dict):
        value = data.get("rewritten_prompt")
        if value is not None and str(value).strip():
            return str(value).strip()
    return cleaned


# --------------------------------------------------------------------------- #
# 参考图
# --------------------------------------------------------------------------- #


def _append_frames(value: Any, sink: list[torch.Tensor], label: str) -> None:
    if value is None:
        return
    if isinstance(value, torch.Tensor):
        tensor = value.detach()
        if tensor.ndim == 3:
            tensor = tensor.unsqueeze(0)
        if tensor.ndim != 4:
            raise ValueError(f"{label} 的图片张量维度不正确（需要 HWC 或 BHWC）")
        for index in range(tensor.shape[0]):
            sink.append(tensor[index : index + 1])
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            _append_frames(item, sink, label)
        return
    raise ValueError(f"{label} 只接受 IMAGE 张量")


def _collect_reference_images(kwargs: dict[str, Any]) -> list[torch.Tensor]:
    """单个列表口；接入顺序就是 `<imageN>` 的序号。

    接 QQ-多媒体加载 的 multi output（列表）时按列表顺序展开，与加载器面板里的序号一致；
    接普通 batch 张量（Load Image 等）时按 batch 维展平，顺序同样即序号。
    """
    images: list[torch.Tensor] = []
    _append_frames(kwargs.get(REFERENCE_INPUT), images, REFERENCE_INPUT)
    if len(images) > MAX_REFERENCE_IMAGES:
        raise ValueError(f"最多支持 {MAX_REFERENCE_IMAGES} 张参考图，当前 {len(images)} 张")
    return images


def _tensor_to_pil(tensor: torch.Tensor) -> Image.Image:
    array = tensor.detach().to(device="cpu", dtype=torch.float32).clamp(0.0, 1.0)
    # 和原节点一致：直接截断成 uint8（不做四舍五入），JPEG 走 progressive。
    array = array.mul(255.0).to(torch.uint8).numpy()
    if array.shape[-1] == 4:
        return Image.fromarray(array, mode="RGBA")
    if array.shape[-1] == 1:
        return Image.fromarray(array[:, :, 0], mode="L")
    return Image.fromarray(array[:, :, :3], mode="RGB")


def _image_to_jpeg_base64(
    tensor: torch.Tensor,
    max_edge: int = DEFAULT_IMAGE_MAX_EDGE,
    quality: int = JPEG_QUALITY,
) -> str:
    """API 通路：等比压到最长边 max_edge，转 RGB JPEG 后返回裸 base64。"""
    frame = tensor[0] if tensor.ndim == 4 else tensor
    image = _tensor_to_pil(frame)
    longest = max(image.size)
    if max_edge and longest > int(max_edge):
        scale = int(max_edge) / float(longest)
        size = (max(1, round(image.width * scale)), max(1, round(image.height * scale)))
        image = image.resize(size, Image.BICUBIC)
    buffer = io.BytesIO()
    image.convert("RGB").save(buffer, format="JPEG", quality=int(quality), progressive=True)
    return base64.b64encode(buffer.getvalue()).decode("ascii")


def _images_to_jpeg_base64(image_sources: Sequence[torch.Tensor]) -> list[str]:
    return [_image_to_jpeg_base64(item) for item in image_sources]


def _resize_image_tensor_max_pixels(
    tensor: torch.Tensor, max_pixels: int = DEFAULT_IMAGE_MAX_PIXELS
) -> torch.Tensor:
    """本地官方 PE 通路：按总像素上限等比缩小，避免视觉 token 爆掉。"""
    height, width = int(tensor.shape[1]), int(tensor.shape[2])
    if height <= 0 or width <= 0 or height * width <= int(max_pixels):
        return tensor
    scale = (float(max_pixels) / float(height * width)) ** 0.5
    size = (max(1, round(width * scale)), max(1, round(height * scale)))
    image = _tensor_to_pil(tensor[0]).resize(size, Image.LANCZOS)
    array = np.asarray(image, dtype=np.float32) / 255.0
    if array.ndim == 2:
        array = array[:, :, None]
    return torch.from_numpy(array).unsqueeze(0).to(dtype=tensor.dtype, device=tensor.device)


def _round_to_multiple(value: float, multiple: int = LONGEST_EDGE_MULTIPLE) -> int:
    return max(multiple, int(round(value / multiple)) * multiple)


def _resize_tensor_to(tensor: torch.Tensor, height: int, width: int) -> torch.Tensor:
    image = _tensor_to_pil(tensor[0]).resize((width, height), Image.LANCZOS)
    array = np.asarray(image, dtype=np.float32) / 255.0
    if array.ndim == 2:
        array = array[:, :, None]
    return torch.from_numpy(array).unsqueeze(0).to(dtype=tensor.dtype, device=tensor.device)


def _scale_longest_edge(tensor: torch.Tensor, threshold: int) -> torch.Tensor:
    """最长边超过阈值时等比缩到阈值，宽高对齐到 32 的倍数；不超过则原样返回。"""
    height, width = int(tensor.shape[1]), int(tensor.shape[2])
    limit = int(threshold)
    longest = max(height, width)
    if limit <= 0 or longest <= limit:
        return tensor
    ratio = limit / float(longest)
    return _resize_tensor_to(tensor, _round_to_multiple(height * ratio), _round_to_multiple(width * ratio))


def _scale_reference_images(images: Sequence[torch.Tensor], threshold: int) -> list[torch.Tensor]:
    return [_scale_longest_edge(item, threshold) for item in images]


def _pe_reference_images(images: Sequence[torch.Tensor]) -> list[torch.Tensor]:
    return [_resize_image_tensor_max_pixels(item) for item in images]


# --------------------------------------------------------------------------- #
# API 通路
# --------------------------------------------------------------------------- #


def _te_man_config_value(key: str) -> str:
    """api_key / api_base_url 留空时，回退读取 TE MAN 插件的 config.ini。"""
    base = getattr(folder_paths, "base_path", None)
    if not base:
        return ""
    path = os.path.join(str(base), "custom_nodes", "TE_MAN", "config.ini")
    try:
        if not os.path.isfile(path):
            return ""
        parser = configparser.ConfigParser()
        parser.read(path, encoding="utf-8")
        value = str(parser.get("gemini", key, fallback="") or "").strip()
    except Exception:
        return ""
    if not value or _PLACEHOLDER_KEY_RE.search(value):
        return ""
    return value


def _resolve_api_url(api_base_url: str) -> str:
    base = str(api_base_url or "").strip().rstrip("/")
    if not base:
        raise ValueError("未配置有效的 API URL")
    if base.endswith("/responses") or base.endswith("/chat/completions"):
        return base
    if base.endswith("/v1"):
        return base + "/responses"
    host = re.sub(r"^https?://", "", base, flags=re.I).split("/", 1)[0].lower()
    if host in _VERSIONLESS_API_HOSTS:
        return base + "/responses"
    return base + "/v1/responses"


def _resolve_api_key(api_key: str) -> str:
    key = str(api_key or "").strip()
    if key:
        return key
    key = _te_man_config_value("api_key")
    if key:
        return key
    raise ValueError("请在节点中填写 API Key，或在 config.ini 中配置 API Key")


def _resolve_api_base_url(api_base_url: str) -> str:
    base = str(api_base_url or "").strip()
    if base:
        return base
    return _te_man_config_value("api_base_url") or DEFAULT_API_BASE_URL


def _normalize_seed(seed: Any) -> int | None:
    """负数种子按「随机」处理，交给 ComfyUI 自己决定。"""
    try:
        value = int(seed)
    except (TypeError, ValueError):
        return None
    return None if value < 0 else value


def _build_api_input(user_prompt: str, image_base64_list: Sequence[str]) -> Any:
    """没有参考图时直接发纯文本 input，有图时才展开成 Responses 的多模态数组。"""
    images = list(image_base64_list or [])
    if not images:
        return user_prompt
    content: list[dict[str, Any]] = [{"type": "input_text", "text": user_prompt}]
    content.extend({"type": "input_image", "image_url": "data:image/jpeg;base64," + item} for item in images)
    return [{"role": "user", "content": content}]


def _extract_response_text(data: dict) -> str:
    """同时兼容 Responses API 的 output 与 chat/completions 的 choices。"""

    def read_content(content: Any) -> str:
        if isinstance(content, str):
            return content
        if isinstance(content, (list, tuple)):
            return "".join(str(part.get("text") or "") for part in content if isinstance(part, dict))
        return ""

    for item in data.get("output") or []:
        if not isinstance(item, dict):
            continue
        text = read_content(item.get("content"))
        if text:
            return text
    output_text = data.get("output_text")
    if isinstance(output_text, str) and output_text:
        return output_text
    for choice in data.get("choices") or []:
        if not isinstance(choice, dict):
            continue
        message = choice.get("message")
        text = read_content(message.get("content") if isinstance(message, dict) else None)
        if text:
            return text
    return ""


def _post_api(url: str, api_key: str, payload: dict[str, Any]) -> dict:
    response = requests.post(
        url,
        json=payload,
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        timeout=API_TIMEOUT,
    )
    if response.status_code != 200:
        raise RuntimeError(f"API 调用失败 HTTP {response.status_code}: {response.text}")
    try:
        data = response.json()
    except ValueError as exc:
        raise RuntimeError(f"API 返回不是合法 JSON：{response.text[:500]}") from exc
    if not isinstance(data, dict):
        raise RuntimeError("API 返回结构不正确，需要一个 JSON 对象")
    return data


def _request_api(
    *,
    api_base_url: str,
    api_key: str,
    model: str,
    instructions: str,
    user_prompt: str,
    image_base64_list: Sequence[str],
) -> str:
    """走 OpenAI Responses 接口；和原节点一样不发送 max_output_tokens。"""
    payload = {
        "model": model,
        "instructions": instructions,
        "input": _build_api_input(user_prompt, image_base64_list),
        "temperature": API_TEMPERATURE,
    }
    data = _post_api(_resolve_api_url(api_base_url), _resolve_api_key(api_key), payload)
    return _extract_response_text(data)


# --------------------------------------------------------------------------- #
# 本地官方 PE 通路
# --------------------------------------------------------------------------- #


def _request_official_pe(
    *,
    model_name: str,
    system_prompt: str,
    user_prompt: str,
    max_output_tokens: int,
    seed: Any,
    thinking: bool,
    images: Sequence[torch.Tensor],
) -> str:
    """按 ComfyUI 文本编码器栈的约定调用：tokenize -> generate -> decode。"""
    clip = _OfficialPEStorage.load(model_name).clip
    text = _build_official_pe_text(system_prompt, user_prompt, has_images=bool(images))
    tokens = clip.tokenize(text, images=list(images), thinking=bool(thinking))
    generated = clip.generate(
        tokens,
        do_sample=True,
        max_length=int(max_output_tokens),
        temperature=PE_TEMPERATURE,
        top_k=PE_TOP_K,
        top_p=PE_TOP_P,
        min_p=0.0,
        repetition_penalty=PE_REPETITION_PENALTY,
        seed=_normalize_seed(seed),
        presence_penalty=0.0,
    )
    return _coerce_text(clip.decode(generated))


