    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs: Any):
        method = str(_first(kwargs.get("增强方式"), METHOD_PE) or METHOD_PE)
        task_mode = str(_first(kwargs.get("任务模式"), MODE_AUTO) or MODE_AUTO)
        if method == METHOD_API:
            if not str(_first(kwargs.get("api_url"), "") or "").strip() and not _te_man_config_value(
                "api_base_url"
            ):
                return "API 方式需要填写 api_url"
            if not str(_first(kwargs.get("api_key"), "") or "").strip() and not _te_man_config_value("api_key"):
                return "API 方式需要填写 api_key（或在本机 TE MAN 的 config.ini 中配置）"
            if not str(_first(kwargs.get("model"), "") or "").strip():
                return "API 方式需要填写 model"
            return True
        if task_mode == MODE_AUTO:
            # 自动模式要等执行时才知道有没有参考图，模型缺失会在执行阶段给出明确报错。
            return True
        model_name = str(
            _first(kwargs.get("图生图PE模型" if task_mode == MODE_IMAGE_TO_IMAGE else "文生图PE模型"), "") or ""
        )
        if not model_name or model_name.startswith("（"):
            return "本地官方PE 需要选择 safetensors PE 模型；请把模型放入 models/text_encoders 或 models/clip"
        return True

    def enhance_prompt(self, **kwargs: Any):
        prompt = str(_first(kwargs.get("输入提示词"), "") or "")
        if not prompt.strip():
            return ("",)
        language = str(_first(kwargs.get("输出语言"), "中文") or "中文")
        method = str(_first(kwargs.get("增强方式"), METHOD_PE) or METHOD_PE)
        task_mode = str(_first(kwargs.get("任务模式"), MODE_AUTO) or MODE_AUTO)
        images = _scale_reference_images(
            _collect_reference_images(kwargs), _as_int(kwargs.get("最长边缩放"), DEFAULT_LONGEST_EDGE)
        )
        mode = (MODE_IMAGE_TO_IMAGE if images else MODE_TEXT_TO_IMAGE) if task_mode == MODE_AUTO else task_mode
        if mode == MODE_IMAGE_TO_IMAGE and not images:
            raise ValueError("图生图模式需要连接图片输入。")
        user_prompt = _USER_REQUEST_PREFIX + prompt
        edit_images = images if mode == MODE_IMAGE_TO_IMAGE else []
        try:
            if method == METHOD_API:
                raw = _request_api(
                    api_base_url=_resolve_api_base_url(str(_first(kwargs.get("api_url"), "") or "")),
                    api_key=str(_first(kwargs.get("api_key"), "") or ""),
                    model=str(_first(kwargs.get("model"), "") or ""),
                    instructions=_build_api_instructions(mode, language),
                    user_prompt=user_prompt,
                    image_base64_list=_images_to_jpeg_base64(edit_images),
                )
            else:
                widget = "图生图PE模型" if mode == MODE_IMAGE_TO_IMAGE else "文生图PE模型"
                model_name = str(_first(kwargs.get(widget), "") or "")
                if not model_name or model_name.startswith("（"):
                    raise ValueError("请选择本地官方PE模型，或把 safetensors 放入 models/text_encoders")
                raw = _request_official_pe(
                    model_name=model_name,
                    system_prompt=_build_official_pe_system(mode, language),
                    user_prompt=user_prompt,
                    max_output_tokens=_as_int(kwargs.get("最大生成token"), DEFAULT_MAX_OUTPUT_TOKENS),
                    seed=_first(kwargs.get("seed"), 0),
                    thinking=_as_bool(kwargs.get("启用思考"), False),
                    images=_pe_reference_images(edit_images),
                )
                if _as_bool(kwargs.get("生成后自动卸载模型"), False):
                    _OfficialPEStorage.unload()
            enhanced = _parse_result(_clean_think_blocks(raw))
        except Exception as exc:
            raise RuntimeError(f"QQ Qwen Image 2.1 提示词增强失败：{exc}") from exc
        return (enhanced,)


